import React, { useEffect, useState, useCallback } from 'react';
import { useAuth } from '../context/AuthContext';
import { tasksService } from '../services/api';
import { CheckCircle, Circle, AlertCircle, XCircle, Plus, Calendar } from 'lucide-react';
import toast from 'react-hot-toast';

const PRIORITIES = {
  low: { label: 'Düşük', color: 'bg-green-100 text-green-700', icon: CheckCircle },
  medium: { label: 'Orta', color: 'bg-yellow-100 text-yellow-700', icon: Circle },
  high: { label: 'Yüksek', color: 'bg-red-100 text-red-700', icon: AlertCircle },
  critical: { label: 'Kritik', color: 'bg-purple-100 text-purple-700', icon: XCircle }
};

const TASK_TYPES = {
  vaccination: 'Aşılama',
  feeding: 'Beslenme',
  cleaning: 'Temizlik',
  health_check: 'Sağlık Kontrolü',
  milking: 'Süt Alma',
  reproduction: 'Üreme',
  financial: 'Finansal',
  maintenance: 'Bakım',
  other: 'Diğer'
};

export default function TasksPage() {
  const { user } = useAuth();
  const farmId = user?.farm_id;

  const [tasks, setTasks] = useState([]);
  const [upcoming, setUpcoming] = useState([]);
  const [loading, setLoading] = useState(true);
  const [filters, setFilters] = useState({ status: 'pending', priority: '' });
  const [showForm, setShowForm] = useState(false);
  const [form, setForm] = useState({
    title: '',
    description: '',
    task_type: 'other',
    due_date: new Date().toISOString().split('T')[0],
    due_time: '',
    priority: 'medium',
    recurring: false,
    recurring_pattern: 'weekly',
    animal_id: '',
    notes: ''
  });

  const load = useCallback(async () => {
    setLoading(true);
    try {
      const [tasksRes, upcomingRes] = await Promise.all([
        tasksService.list(farmId, filters),
        tasksService.upcoming(farmId, { days: 7 })
      ]);
      setTasks(tasksRes.data.data || []);
      setUpcoming(upcomingRes.data.data || []);
    } catch {
      toast.error('Görevler yüklenemedi');
    } finally {
      setLoading(false);
    }
  }, [farmId, filters]);

  useEffect(() => { load(); }, [load]);

  const handleAdd = async (e) => {
    e.preventDefault();
    if (!form.title || !form.due_date) {
      toast.error('Başlık ve tarih zorunlu');
      return;
    }
    try {
      const payload = {
        ...form,
        animal_id: form.animal_id ? parseInt(form.animal_id) : null
      };
      await tasksService.create(farmId, payload);
      toast.success('Görev eklendi');
      setShowForm(false);
      setForm({
        title: '',
        description: '',
        task_type: 'other',
        due_date: new Date().toISOString().split('T')[0],
        due_time: '',
        priority: 'medium',
        recurring: false,
        recurring_pattern: 'weekly',
        animal_id: '',
        notes: ''
      });
      load();
    } catch (err) {
      toast.error(err.response?.data?.error || 'İşlem başarısız');
    }
  };

  const handleComplete = async (taskId) => {
    try {
      await tasksService.complete(farmId, taskId, '');
      toast.success('Görev tamamlandı');
      load();
    } catch {
      toast.error('İşlem başarısız');
    }
  };

  return (
    <div className="space-y-6">
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4">
        <div>
          <h1 className="text-2xl font-bold text-gray-900">✅ Görev Yönetimi</h1>
          <p className="text-sm text-gray-500">Çiftlik işleri ve randevu takibi</p>
        </div>
        <button onClick={() => setShowForm(!showForm)} className={`btn-primary flex items-center justify-center gap-2 ${showForm ? 'bg-red-500 hover:bg-red-600' : ''}`}>
          {showForm ? 'İptal' : <><Plus className="w-4 h-4" /> Görev Ekle</>}
        </button>
      </div>

      {/* Yaklaşan görevler */}
      {upcoming.length > 0 && (
        <div className="card border-l-4 border-blue-500 bg-blue-50/10">
          <div className="flex items-center gap-2 mb-4">
             <Calendar className="w-5 h-5 text-blue-600" />
             <h3 className="font-bold text-gray-900">Yaklaşan Görevler (7 Gün)</h3>
          </div>
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-3">
            {upcoming.slice(0, 6).map(t => (
              <div key={t.id} className="flex items-center justify-between p-3 bg-white border border-blue-100 rounded-2xl shadow-sm group hover:border-blue-300 transition-colors">
                <div className="min-w-0">
                  <p className="font-bold text-gray-900 truncate">{t.title}</p>
                  <p className="text-[10px] text-gray-500 font-medium uppercase mt-0.5">{t.due_date} • {TASK_TYPES[t.task_type] || 'Diğer'}</p>
                </div>
                <span className={`px-2 py-1 rounded-lg text-[9px] font-black uppercase tracking-wider whitespace-nowrap ${PRIORITIES[t.priority]?.color}`}>
                  {PRIORITIES[t.priority]?.label}
                </span>
              </div>
            ))}
          </div>
        </div>
      )}

      {/* Form */}
      {showForm && (
        <div className="card border-orange-100 bg-orange-50/20 animate-in fade-in slide-in-from-top-4">
          <h2 className="text-lg font-bold mb-4 text-orange-900">Yeni Görev Tanımla</h2>
          <form onSubmit={handleAdd} className="space-y-4">
            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
              <div className="md:col-span-2">
                <label className="block text-xs font-bold text-gray-400 uppercase mb-1 ml-1">Görev Başlığı</label>
                <input
                  type="text"
                  placeholder="Örn: A-045 nolu hayvanın aşılanması"
                  value={form.title}
                  onChange={e => setForm({ ...form, title: e.target.value })}
                  className="input-field"
                  required
                />
              </div>
              <div>
                <label className="block text-xs font-bold text-gray-400 uppercase mb-1 ml-1">Görev Türü</label>
                <select
                  value={form.task_type}
                  onChange={e => setForm({ ...form, task_type: e.target.value })}
                  className="input-field"
                >
                  {Object.entries(TASK_TYPES).map(([k, v]) => (
                    <option key={k} value={k}>{v}</option>
                  ))}
                </select>
              </div>
              <div>
                <label className="block text-xs font-bold text-gray-400 uppercase mb-1 ml-1">Öncelik</label>
                <select
                  value={form.priority}
                  onChange={e => setForm({ ...form, priority: e.target.value })}
                  className="input-field"
                >
                  <option value="low">Düşük</option>
                  <option value="medium">Orta</option>
                  <option value="high">Yüksek</option>
                  <option value="critical">Kritik</option>
                </select>
              </div>
              <div>
                <label className="block text-xs font-bold text-gray-400 uppercase mb-1 ml-1">Son Tarih</label>
                <input
                  type="date"
                  value={form.due_date}
                  onChange={e => setForm({ ...form, due_date: e.target.value })}
                  className="input-field"
                  required
                />
              </div>
              <div>
                <label className="block text-xs font-bold text-gray-400 uppercase mb-1 ml-1">Saat (Opsiyonel)</label>
                <input
                  type="time"
                  value={form.due_time}
                  onChange={e => setForm({ ...form, due_time: e.target.value })}
                  className="input-field"
                />
              </div>
            </div>
            
            <div className="flex flex-col sm:flex-row items-start sm:items-center gap-4 bg-white/50 p-4 rounded-2xl border border-orange-100">
              <label className="flex items-center gap-2 cursor-pointer group">
                <input
                  type="checkbox"
                  checked={form.recurring}
                  onChange={e => setForm({ ...form, recurring: e.target.checked })}
                  className="w-5 h-5 rounded-lg text-orange-600 focus:ring-orange-500"
                />
                <span className="text-sm font-bold text-gray-700 group-hover:text-orange-700 transition-colors">Tekrarlayan Görev</span>
              </label>
              {form.recurring && (
                <select
                  value={form.recurring_pattern}
                  onChange={e => setForm({ ...form, recurring_pattern: e.target.value })}
                  className="input-field py-1.5 h-auto text-sm"
                >
                  <option value="daily">Her Gün</option>
                  <option value="weekly">Her Hafta</option>
                  <option value="monthly">Her Ay</option>
                </select>
              )}
            </div>

            <div>
              <label className="block text-xs font-bold text-gray-400 uppercase mb-1 ml-1">Açıklama / Notlar</label>
              <textarea
                placeholder="Görev hakkında detaylı bilgi yazın..."
                value={form.description}
                onChange={e => setForm({ ...form, description: e.target.value })}
                className="input-field"
                rows={2}
              />
            </div>
            
            <div className="flex gap-3">
              <button type="button" onClick={() => setShowForm(false)} className="btn-secondary flex-1">Vazgeç</button>
              <button type="submit" className="btn-primary flex-1">Görevi Oluştur</button>
            </div>
          </form>
        </div>
      )}

      {/* Filtreler */}
      <div className="card p-4">
        <div className="flex flex-col md:flex-row gap-3">
          <select
            value={filters.status}
            onChange={e => { setFilters({ ...filters, status: e.target.value }); }}
            className="input-field flex-1"
          >
            <option value="pending">⏳ Bekleyen Görevler</option>
            <option value="in_progress">🔄 Devam Edenler</option>
            <option value="completed">✅ Tamamlananlar</option>
          </select>
          <select
            value={filters.priority}
            onChange={e => { setFilters({ ...filters, priority: e.target.value }); }}
            className="input-field flex-1"
          >
            <option value="">Tüm Öncelikler</option>
            <option value="low">Düşük Öncelik</option>
            <option value="medium">Orta Öncelik</option>
            <option value="high">Yüksek Öncelik</option>
            <option value="critical">Kritik Öncelik</option>
          </select>
          <button onClick={load} className="btn-secondary px-8">Filtrele</button>
        </div>
      </div>

      {/* Görev Listesi */}
      <div className="card p-0 overflow-hidden">
        <div className="overflow-x-auto">
          {loading ? (
            <div className="flex items-center justify-center py-12">
              <div className="w-8 h-8 border-4 border-orange-600 border-t-transparent rounded-full animate-spin" />
            </div>
          ) : tasks.length === 0 ? (
            <div className="text-center py-12 text-gray-400">
              <div className="text-4xl mb-2">✨</div>
              <p className="font-medium text-sm">Harika! Bekleyen görev bulunmuyor.</p>
            </div>
          ) : (
            <table className="w-full text-sm">
              <thead className="bg-gray-50 border-b">
                <tr>
                  <th className="text-left px-6 py-4 font-bold text-gray-400 uppercase tracking-wider text-[10px]">Görev</th>
                  <th className="text-left px-6 py-4 font-bold text-gray-400 uppercase tracking-wider text-[10px]">Tür</th>
                  <th className="text-left px-6 py-4 font-bold text-gray-400 uppercase tracking-wider text-[10px]">Vade</th>
                  <th className="text-left px-6 py-4 font-bold text-gray-400 uppercase tracking-wider text-[10px]">Öncelik</th>
                  <th className="text-right px-6 py-4 font-bold text-gray-400 uppercase tracking-wider text-[10px]">İşlem</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-gray-100">
                {tasks.map(t => (
                  <tr key={t.id} className="hover:bg-gray-50 transition-colors group">
                    <td className="px-6 py-4">
                       <p className="font-bold text-gray-900">{t.title}</p>
                       <p className="text-xs text-gray-500 mt-0.5 max-w-xs truncate">{t.description || 'Açıklama yok'}</p>
                    </td>
                    <td className="px-6 py-4 whitespace-nowrap">
                      <span className="text-gray-600 font-medium">{TASK_TYPES[t.task_type] || 'Diğer'}</span>
                    </td>
                    <td className="px-6 py-4 whitespace-nowrap text-gray-600">{t.due_date}</td>
                    <td className="px-6 py-4 whitespace-nowrap">
                      <span className={`px-2 py-1 rounded-lg text-[9px] font-black uppercase tracking-wider ${PRIORITIES[t.priority]?.color}`}>
                        {PRIORITIES[t.priority]?.label}
                      </span>
                    </td>
                    <td className="px-6 py-4 text-right whitespace-nowrap">
                      {t.status !== 'completed' && (
                        <button
                          onClick={() => handleComplete(t.id)}
                          className="btn-primary text-xs py-1.5 px-3 bg-green-600 hover:bg-green-700 shadow-sm shadow-green-600/20"
                        >
                          Tamamla
                        </button>
                      )}
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          )}
        </div>
      </div>
    </div>
  );
}
